dates.fraction.code:
fn fraction(s: &[u8]) -> Option<(i64, usize)> {
    let mut i = 19; let mut nano = 0;
    if s[i] == b'.' {
        i += 1; let first = i; let mut multiplier = 100000000;
        while i < s.len() && s[i] >= b'0' && s[i] <= b'9' {
            nano += (s[i] - b'0') as i64 * multiplier;
            multiplier /= 10; i += 1;
        }
        if i == first { return None; }
    }
    Some((nano, i))
}

