        v.push(ctx.username.clone());
        return Some(v);
    }
    if bytes::eq(name, b"aws:userid") {
        return userid_strings(&ctx.claims);
    }
    match resolve(ctx, name) {
        Some(s) => {
            let mut v = Vec::new();
            v.push(s);
            Some(v)
        }
        None => None,
    }
}

