fn splice(results: &[Pending], i: usize, new: &[Pending]) -> Vec<Pending> {
    let mut out = Vec::new();
    let mut k = 0;
    while k < i {
        out.push(pending_clone(&results[k]));
        k += 1;
    }
    let mut j = 0;
    while j < new.len() {
        out.push(pending_clone(&new[j]));
        j += 1;
    }
    let mut k2 = i + 1;
    while k2 < results.len() {
        out.push(pending_clone(&results[k2]));
        k2 += 1;
    }
    out
}

