pub fn replace(s: &[u8], from: &[u8], to: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < s.len() {
        if from.len() > 0 && starts_with_at(s, i, from) {
            let mut j = 0;
            while j < to.len() {
                out.push(to[j]);
                j += 1;
            }
            i += from.len();
        } else {
            out.push(s[i]);
            i += 1;
        }
    }
    out
}

