pub fn starts_with_at(s: &[u8], from: usize, p: &[u8]) -> bool {
    if from > s.len() || s.len() - from < p.len() {
        return false;
    }
    let mut i = 0;
    while i < p.len() {
        if s[from + i] != p[i] {
            return false;
        }
        i += 1;
    }
    true
}

