fn replace_first_common(c: &[u8], values: &CondValues) -> Vec<u8> {
    let mut k = 0;
    while k < COMMON_KEYS_LEN {
        let (name, var_name) = common_key(k);
        match get_value(values, &name) {
            Some(vs) => {
                if vs.len() > 0 && vs[0].len() > 0 {
                    return bytes::replace(c, &var_name, &vs[0]);
                }
            }
            None => {}
        }
        k += 1;
    }
    c.to_vec()
}

