wildmatch.deep_match.code:
fn deep_match(p: &[u8], pi: usize, n: &[u8], ni: usize, simple: bool) -> bool {
    if pi >= p.len() {
        return ni >= n.len();
    }
    let c = p[pi];
    if c == b'?' {
        if ni >= n.len() {
            return simple;
        }
        return deep_match(p, pi + 1, n, ni + 1, simple);
    }
    if c == b'*' {
        return p.len() - pi == 1
            || deep_match(p, pi + 1, n, ni, simple)
            || (ni < n.len() && deep_match(p, pi, n, ni + 1, simple));
    }
    if ni >= n.len() || n[ni] != c {
        return false;
    }
    deep_match(p, pi + 1, n, ni + 1, simple)
}

wildmatch.inner_match.code:
fn inner_match(pattern: &[u8], name: &[u8], simple: bool) -> bool {
    if pattern.len() == 0 {
        return name.len() == 0;
    }
    if pattern.len() == 1 && pattern[0] == b'*' {
        return true;
    }
    deep_match(pattern, 0, name, 0, simple)
}

wildmatch.is_match.code:
pub fn is_match(pattern: &[u8], name: &[u8]) -> bool {
    inner_match(pattern, name, false)
}

bytes.parse_digits.code:
fn parse_digits(s: &[u8], i: usize, acc: i64, neg: bool) -> Option<i64> {
    if i >= s.len() {
        return Some(acc);
    }
    let c = s[i];
    if c < b'0' || c > b'9' {
        return None;
    }
    let d = (c - b'0') as i64;
    let m = match acc.checked_mul(10) {
        Some(m) => m,
        None => return None,
    };
    let next = if neg { m.checked_sub(d) } else { m.checked_add(d) };
    match next {
        Some(v) => parse_digits(s, i + 1, v, neg),
        None => None,
    }
}

bytes.parse_i64.code:
pub fn parse_i64(s: &[u8]) -> Option<i64> {
    if s.len() == 0 {
        return None;
    }
    let neg = s[0] == b'-';
    let start = if s[0] == b'-' || s[0] == b'+' { 1 } else { 0 };
    if start == s.len() {
        return None;
    }
    parse_digits(s, start, 0, neg)
}

