condfuncs.net_contains.code:
fn net_contains(net: IpAddr, prefix: u8, ip: IpAddr) -> bool {
    match (net, ip) {
        (IpAddr::V4(n), IpAddr::V4(a)) => {
            if prefix == 0 {
                return true;
            }
            if prefix >= 32 {
                return n == a;
            }
            (n >> (32 - prefix)) == (a >> (32 - prefix))
        }
        (IpAddr::V6(n), IpAddr::V6(a)) => {
            if prefix == 0 {
                return true;
            }
            if prefix >= 128 {
                return n == a;
            }
            (n >> (128 - prefix)) == (a >> (128 - prefix))
        }
        _ => false,
    }
}

