    let mut out = pattern.to_vec();
    let mut k = 0;
    while k < COMMON_KEYS_LEN {
        let (name, var_name) = common_key(k);
        match get_value(conditions, &name) {
            Some(vs) => {
                if vs.len() > 0 && vs[0].len() > 0 {
                    out = bytes::replace(&out, &var_name, &vs[0]);
                }
            }
            None => {}
        }
        k += 1;
    }
    out
}

