pub fn scalar_at(s: &[u8], i: usize) -> (u32, usize) {
    let first = s[i] as u32;
    if first < 128 {
        return (first, i + 1);
    }
    if first < 224 {
        return (((first & 31) << 6) | (s[i + 1] as u32 & 63), i + 2);
    }
    if first < 240 {
        return (
            ((first & 15) << 12) | ((s[i + 1] as u32 & 63) << 6) | (s[i + 2] as u32 & 63),
            i + 3,
