unicode.within.code:
fn within(cp: u32, start: u32, end: u32, parity: u32) -> bool {
    if cp < start || cp > end {
        return false;
    }
    parity == 0 || cp % 2 == parity - 1
}

unicode.trim.code:
pub fn trim(s: &[u8]) -> Vec<u8> {
    let mut first = s.len();
    let mut last = 0;
    let mut i = 0;
    while i < s.len() {
        let (cp, next) = scalar_at(s, i);
        if !whitespace(cp) {
            if first == s.len() {
                first = i;
            }
            last = next;
        }
        i = next;
    }
    if first == s.len() {
        Vec::new()
    } else {
        crate::bytes::slice(s, first, last)
    }
}

