    while i < pattern.len() && i < text.len() {
        let x = pattern[i];
        let y = text[i];
        if x == b'*' {
            return true;
        }
        if x != b'?' && x != y {
            return false;
        }
        i += 1;
    }
    text.len() <= pattern.len()
}

