pub fn base64_digit(c: u8) -> Option<u8> {
    if c >= b'A' && c <= b'Z' {
        return Some(c - b'A');
    }
    if c >= b'a' && c <= b'z' {
        return Some(c - b'a' + 26);
    }
    if c >= b'0' && c <= b'9' {
        return Some(c - b'0' + 52);
    }
    if c == b'+' {
        return Some(62);
    }
    if c == b'/' {
        return Some(63);
    }
    None
}

