        Some(c) => c,
        None => return None,
    };
    let i = match find(table, name) {
        Some(i) => i,
        None => return None,
    };
    match &table[i].1 {
        Value::Array(array) => Some(array_strings(array)),
        value => match scalar_string(value) {
            Some(s) => Some({
                let mut __v = Vec::new();
                __v.push(s);
