pub fn split_values(s: &[u8]) -> Vec<Vec<u8>> {
    let mut out = Vec::new();
    let mut start = 0;
    let mut i = 0;
    while i <= s.len() {
        if i == s.len() || s[i] == b',' {
            let part = unicode::trim(&bytes::slice(s, start, i));
            if part.len() != 0 {
                out.push(part);
            }
            start = i + 1;
        }
        i += 1;
    }
    out
}

