/// Single pass resolution of variables in a string
async fn resolve_single_pass(pattern: &str, resolver: &dyn PolicyVariableResolver) -> Vec<String> {
    // Find all ${...} format variables
    let mut results = vec![pattern.to_string()];

    // Process each result string
    let mut i = 0;
    while i < results.len() {
        let mut start = 0;
        let mut modified = false;

        // Find variables in current string
        while let Some(pos) = results[i][start..].find("${") {
            let actual_pos = start + pos;

            // Find the matching closing brace, taking into account nested braces
            let mut brace_count = 1;
            let mut end_pos = actual_pos + 2; // Start after "${"

            let bytes = results[i].as_bytes();
            while end_pos < bytes.len() && brace_count > 0 {
                match bytes[end_pos] {
                    b'{' => brace_count += 1,
                    b'}' => brace_count -= 1,
                    _ => {}
                }
                if brace_count > 0 {
                    end_pos += 1;
                }
            }

            if brace_count == 0 {
                let var_name = &results[i][actual_pos + 2..end_pos];

                // Check if this is a nested variable (contains ${...} inside)
                if var_name.contains("${") {
                    // For nested variables like ${${a}-${b}}, we need to resolve the inner variables first
                    // Then use the resolved result as a new variable to resolve
                    let resolved_inner = resolve_aws_variables_boxed(var_name, resolver).await;
                    let mut new_results = Vec::new();

                    for resolved_var_name in resolved_inner {
                        let prefix = &results[i][..actual_pos];
                        let suffix = &results[i][end_pos + 1..];
                        new_results.push(format!("{prefix}{resolved_var_name}{suffix}"));
                    }

                    if !new_results.is_empty() {
                        // Update result set
                        results.splice(i..i + 1, new_results);
                        modified = true;
                        break;
                    } else {
                        // If we couldn't resolve the nested variable, keep the original
                        start = end_pos + 1;
                    }
                } else {
                    // Regular variable resolution
                    if let Some(values) = resolver.resolve_multiple(var_name).await {
                        if !values.is_empty() {
                            // If there are multiple values, create a new result for each value
                            let mut new_results = Vec::new();
                            let prefix = &results[i][..actual_pos];
                            let suffix = &results[i][end_pos + 1..];

                            for value in values {
                                new_results.push(format!("{prefix}{value}{suffix}"));
                            }

                            results.splice(i..i + 1, new_results);
                            modified = true;
                            break;
                        } else {
                            // Variable resolved to empty, just remove the variable placeholder
                            let mut new_results = Vec::new();
                            let prefix = &results[i][..actual_pos];
                            let suffix = &results[i][end_pos + 1..];
                            new_results.push(format!("{prefix}{suffix}"));

                            results.splice(i..i + 1, new_results);
                            modified = true;
                            break;
                        }
                    } else {
                        // Variable not found, skip
                        start = end_pos + 1;
                    }
                }
            } else {
                // No matching closing brace found, break loop
                break;
            }
        }

        if !modified {
            i += 1;
        }
    }

    results
}

crates/policy/src/policy/function/string.code:
async fn eval(
    &self,
    quantifier: Quantifier,
    ignore_case: bool,
    negate: bool,
    values: &HashMap<String, Vec<String>>,
    resolver: Option<&dyn PolicyVariableResolver>,
) -> bool {
    let rvalues = values
        // http.CanonicalHeaderKey ?
        .get(self.key.name().as_str())
        .map(|t| {
            t.iter()
                .map(|x| {
                    if ignore_case {
                        Cow::Owned(x.to_lowercase())
                    } else {
                        Cow::from(x)
                    }
                })
                .collect::<Set<_>>()
        })
        .unwrap_or_default();

    let resolved_values: Vec<Vec<String>> = futures::future::join_all(self.values.0.iter().map(|c| async {
        if let Some(res) = resolver {
            super::super::variables::resolve_aws_variables(c, res).await
        } else {
            vec![c.to_string()]
        }
    }))
    .await;

    let fvalues = resolved_values
        .into_iter()
        .flatten()
        .map(|resolved_c| {
            let mut c = Cow::from(resolved_c);
            for key in KeyName::COMMON_KEYS {
                match values.get(key.name()).and_then(|x| x.first()) {
                    Some(v) if !v.is_empty() => return Cow::Owned(c.to_mut().replace(&key.var_name(), v)),
                    _ => continue,
                };
            }

            c
        })
        .map(|x| if ignore_case { Cow::Owned(x.to_lowercase()) } else { x })
        .collect::<Set<_>>();

    match quantifier {
        // Unqualified: the operator applies to the value set as a whole. The caller
        // negates the aggregate, so report the plain "some value matched" result.
        Quantifier::None => rvalues.intersection(&fvalues).count() > 0,
        // Qualified: quantify over the per-value predicate, negation included.
        Quantifier::ForAllValues => rvalues.iter().all(|v| fvalues.contains(v) ^ negate),
        Quantifier::ForAnyValue => rvalues.iter().any(|v| fvalues.contains(v) ^ negate),
    }
}

async fn eval_like(
    &self,
    quantifier: Quantifier,
    negate: bool,
    values: &HashMap<String, Vec<String>>,
    resolver: Option<&dyn PolicyVariableResolver>,
) -> bool {
    if let Some(rvalues) = values.get(self.key.name().as_str()) {
        for v in rvalues.iter() {
            let resolved_futures: Vec<_> = self
                .values
                .0
                .iter()
                .map(|c| async {
                    if let Some(res) = resolver {
                        super::super::variables::resolve_aws_variables(c, res).await
                    } else {
                        vec![c.to_string()]
                    }
                })
                .collect();
            let resolved_values = future::join_all(resolved_futures).await;
            let matched = resolved_values
                .into_iter()
                .flatten()
                .map(|resolved_c| {
                    let mut c = Cow::from(resolved_c);
                    for key in KeyName::COMMON_KEYS {
                        match values.get(key.name()).and_then(|x| x.first()) {
                            Some(v) if !v.is_empty() => return Cow::Owned(c.to_mut().replace(&key.var_name(), v)),
                            _ => continue,
                        };
                    }

                    c
                })
                .any(|x| wildcard::is_match(x, v));

            // Unqualified evaluation reports the plain aggregate match and lets the
            // caller negate it; the qualifiers fold negation into the per-value
            // predicate so that ForAllValues/ForAnyValue keep their own meaning.
            let holds = match quantifier {
                Quantifier::None => matched,
                Quantifier::ForAllValues | Quantifier::ForAnyValue => matched ^ negate,
            };

            match quantifier {
                Quantifier::ForAllValues => {
                    if !holds {
                        return false;
                    }
                }
                Quantifier::None | Quantifier::ForAnyValue => {
                    if holds {
                        return true;
                    }
                }
            }
        }
    }

    // No request value settled it: ForAllValues is vacuously satisfied, the other
    // two are not.
    quantifier == Quantifier::ForAllValues
}

#[allow(clippy::too_many_arguments)]
pub(crate) async fn evaluate_with_resolver(
    &self,
    quantifier: Quantifier,
    ignore_case: bool,
    like: bool,
    negate: bool,
    values: &HashMap<String, Vec<String>>,
    resolver: Option<&dyn PolicyVariableResolver>,
) -> bool {
    for inner in self.0.iter() {
        // For `ForAllValues:`/`ForAnyValue:` the negation belongs to the per-value
        // predicate, so it is pushed down into eval/eval_like. Without a qualifier
        // the operator applies to the value set as a whole and the aggregate is
        // negated here, which preserves AWS single-valued-key semantics.
        let result = match quantifier {
            Quantifier::None => {
                let matched = if like {
                    inner.eval_like(quantifier, false, values, resolver).await
                } else {
                    inner.eval(quantifier, ignore_case, false, values, resolver).await
                };
                matched ^ negate
            }
            Quantifier::ForAnyValue | Quantifier::ForAllValues => {
                if like {
                    inner.eval_like(quantifier, negate, values, resolver).await
                } else {
                    inner.eval(quantifier, ignore_case, negate, values, resolver).await
                }
            }
        };

        if !result {
            return false;
        }
    }

    true
}

